INSERT OR IGNORE INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a45','Quem cuida do que fica depois da festa','quem-cuida-do-que-fica-depois-da-festa','A desmontagem de um evento revela uma cadeia de trabalho que começa antes da abertura dos portões e continua quando o público vai embora.','["Quando a música termina, o espaço muda de função. Copos precisam ser recolhidos, cabos organizados, estruturas desmontadas e materiais separados. Para o público, o evento chegou ao fim; para várias equipes, começa uma etapa que exige atenção e coordenação.","A montagem e a desmontagem dependem de tarefas diferentes, mas conectadas. Uma estrutura mal identificada pode atrasar a retirada; um corredor bloqueado pode dificultar a passagem de equipamentos. Planejar o encerramento com o mesmo cuidado da abertura reduz improvisos e protege quem trabalha no local.","Também há decisões sobre o destino dos materiais. O que pode ser reaproveitado precisa ser separado sem contaminar outros resíduos, e os responsáveis pelo espaço devem saber como será feita a limpeza. Uma promessa genérica de sustentabilidade não substitui esse plano prático.","O trabalho costuma ser menos visível do que o palco, embora sustente a experiência. Conhecer funções e horários ajuda a reconhecer a contribuição de equipes técnicas, limpeza, segurança, transporte e produção sem transformar profissionais em cenário.","Um evento responsável pensa no depois antes de começar. O retorno do espaço ao uso cotidiano faz parte da organização e precisa entrar no orçamento, no cronograma e na comunicação com quem participa."]','trabalho','lucas-reis','','Fotografia editorial relacionada à matéria: Quem cuida do que fica depois da festa','published',0,1,'2026-10-30T12:00:00.000Z','2026-10-30T12:00:00.000Z','Quem cuida do que fica depois da festa | Pé de Prosa','A desmontagem de um evento revela uma cadeia de trabalho que começa antes da abertura dos portões e continua quando o público vai embora.');
