INSERT OR IGNORE INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a47','A conversa difícil de dividir o cuidado','conversa-dificil-dividir-cuidado','Organizar tarefas de cuidado exige tornar visível o trabalho diário e combinar responsabilidades que mudam conforme a necessidade.','["Em muitas casas, o cuidado aparece como uma lista de tarefas pequenas: preparar uma refeição, acompanhar um compromisso, lembrar um horário, organizar a roupa e perceber quando alguém precisa de ajuda. Como cada tarefa parece rápida, o volume total pode ficar escondido.","A divisão costuma falhar quando depende apenas de pedidos feitos na última hora. Planejar quem assume cada parte e combinar como avisar sobre mudanças reduz a expectativa de que uma pessoa esteja sempre disponível para perceber tudo.","O acordo precisa levar em conta tempo, capacidade e preferência. Uma tarefa pode ser compartilhada em etapas; outra exige continuidade ou conhecimento específico. Distribuir responsabilidades não significa que todas as pessoas farão exatamente o mesmo, e sim que ninguém fica sem uma forma de participação.","Também é importante revisar os combinados. Trabalho, saúde e rotina mudam; um arranjo que funcionava antes pode se tornar pesado. Conversar sobre o que não está dando certo é mais produtivo quando o foco está nas condições e nas soluções, sem transformar a conversa em julgamento pessoal.","Cuidado não é apenas uma intenção afetuosa. É trabalho concreto, com limites e necessidades. Dar nome a esse trabalho ajuda a construir relações mais sustentáveis para quem recebe e para quem oferece apoio."]','cotidiano','joana-melo','','Fotografia editorial relacionada à matéria: A conversa difícil de dividir o cuidado','published',0,2,'2026-10-28T12:00:00.000Z','2026-10-28T12:00:00.000Z','A conversa difícil de dividir o cuidado | Pé de Prosa','Organizar tarefas de cuidado exige tornar visível o trabalho diário e combinar responsabilidades que mudam conforme a necessidade.');
