INSERT OR IGNORE INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a52','O livro que circula de mão em mão','livro-circula-de-mao-em-mao','Empréstimos informais criam rotas de leitura e acrescentam histórias pessoais às páginas que passam por uma comunidade.','["Um livro emprestado carrega dois percursos. Há o caminho escrito pelo autor e outro feito pelas pessoas que o levam para casa, deixam na mochila e recomendam a alguém. A capa começa a reunir marcas de uso que não alteram o texto, mas contam algo sobre a circulação.","Às vezes, a leitura acontece em ritmos diferentes. Uma pessoa termina em poucos dias; outra precisa devolver antes de chegar ao último capítulo. O empréstimo depende de combinados simples e de um modo de manter contato, mas também da confiança de que o livro encontrará outro leitor.","Esse movimento amplia o acesso sem exigir uma coleção grande em cada casa. Uma vizinha pode compartilhar um romance, um colega indicar um ensaio e uma família deixar títulos infantis disponíveis para crianças que estão aprendendo a escolher o que querem ler.","Para que o circuito continue, ajuda registrar de quem veio o exemplar e combinar como será devolvido. Não é preciso transformar a troca em burocracia; basta que as expectativas sejam claras para evitar que a vontade de compartilhar termine em mal-entendido.","Quando um livro passa adiante, a leitura deixa de ser uma experiência completamente solitária. O comentário escrito na conversa, a recomendação e a lembrança do empréstimo continuam ao redor da história depois que a última página é virada."]','cultura','ana-luz','','Fotografia editorial relacionada à matéria: O livro que circula de mão em mão','published',0,2,'2026-10-23T12:00:00.000Z','2026-10-23T12:00:00.000Z','O livro que circula de mão em mão | Pé de Prosa','Empréstimos informais criam rotas de leitura e acrescentam histórias pessoais às páginas que passam por uma comunidade.');
