INSERT OR IGNORE INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a53','As pequenas reparações que mudam o uso de um espaço','pequenas-reparacoes-mudam-uso-espaco','Uma lâmpada substituída, um banco firme ou uma placa legível podem fazer diferença na maneira como as pessoas usam um lugar comum.','["Nem toda mudança em um espaço compartilhado exige uma obra grande. Uma luminária funcionando, um banco estável ou uma placa em bom estado podem resolver dificuldades que afastam pessoas de uma praça, de um corredor ou de uma sala comunitária.","O tamanho da intervenção não deve esconder a necessidade de entender quem usa o lugar. Uma melhoria pensada para um grupo pode bloquear a circulação de outro; por isso, observar os horários e conversar com diferentes usuários ajuda a definir prioridades.","Também é importante saber quem pode executar cada reparo. Instalações elétricas, estruturas altas e equipamentos danificados podem exigir profissionais. Comunidade e gestores podem registrar o problema, proteger a área e encaminhar a solicitação sem transformar boa vontade em risco.","Pequenas correções funcionam melhor quando há acompanhamento. Depois do conserto, alguém precisa verificar se a solução continua adequada e se outras barreiras apareceram. Cuidar de um espaço é um processo, não apenas uma fotografia de inauguração.","A atenção ao detalhe mostra que o uso cotidiano importa. Um lugar se torna mais acolhedor quando suas condições básicas permitem que as pessoas permaneçam sem precisar superar obstáculos evitáveis."]','ideias','bia-sampaio','','Fotografia editorial relacionada à matéria: As pequenas reparações que mudam o uso de um espaço','published',0,1,'2026-10-22T12:00:00.000Z','2026-10-22T12:00:00.000Z','As pequenas reparações que mudam o uso de um espaço | Pé de Prosa','Uma lâmpada substituída, um banco firme ou uma placa legível podem fazer diferença na maneira como as pessoas usam um lugar comum.');
