INSERT OR IGNORE INTO articles (id,title,slug,excerpt,body_json,category_id,author_id,cover,alt_text,status,featured,reading_minutes,published_at,updated_at,seo_title,seo_description) VALUES ('a54','A pausa para o café como medida do tempo','pausa-cafe-medida-tempo','O intervalo compartilhado organiza conversas e ritmos de trabalho, mas também revela quem consegue interromper a jornada.','["Em alguns locais, o café marca uma pausa reconhecida por todos. Em outros, cada pessoa encontra um intervalo quando a tarefa permite. A bebida pode ser a mesma, mas as condições para parar variam conforme a escala, o atendimento e a responsabilidade de manter o serviço em funcionamento.","Uma pausa coletiva aproxima colegas que passam boa parte do dia concentrados em tarefas diferentes. É nesse momento que dúvidas são esclarecidas, avisos circulam e assuntos sem relação imediata com o trabalho encontram espaço.","O intervalo também pode reproduzir desigualdades quando alguns conseguem se afastar enquanto outros precisam permanecer disponíveis. Planejar cobertura e revezamento torna a pausa mais justa e evita que ela dependa de quem tem menos poder para interromper a atividade.","Conversas informais ajudam, mas não substituem orientações claras sobre horários e direitos. Cada ambiente tem regras próprias, e conhecer os acordos aplicáveis é importante para que uma pausa necessária não seja tratada como favor pessoal.","Olhar para o café como medida do tempo revela como uma organização entende descanso e convivência. O intervalo não precisa ser longo para ter valor; precisa existir de maneira previsível e compatível com a jornada."]','trabalho','maira-costa','','Fotografia editorial relacionada à matéria: A pausa para o café como medida do tempo','published',0,1,'2026-10-21T12:00:00.000Z','2026-10-21T12:00:00.000Z','A pausa para o café como medida do tempo | Pé de Prosa','O intervalo compartilhado organiza conversas e ritmos de trabalho, mas também revela quem consegue interromper a jornada.');
